#!/usr/bin/env python3
"""Writes Coo.Mobile.Presentation/Resources/AppResources*.resx from strings.py (ADR 0006 §2)."""
import os, sys
from xml.sax.saxutils import escape
sys.path.insert(0, os.path.dirname(__file__))
from strings import LANGS, S, P

out = os.path.join(os.path.dirname(__file__), '..', '..', 'src', 'Mobile', 'Coo.Mobile.Presentation', 'Resources')
os.makedirs(out, exist_ok=True)
header = '''<?xml version="1.0" encoding="utf-8"?>
<!-- Generated by eng/strings/generate.py from eng/strings/strings.py. Edit those, not this file. -->
<root>
  <resheader name="resmimetype"><value>text/microsoft-resx</value></resheader>
  <resheader name="version"><value>2.0</value></resheader>
  <resheader name="reader"><value>System.Resources.ResXResourceReader, System.Windows.Forms, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089</value></resheader>
  <resheader name="writer"><value>System.Resources.ResXResourceWriter, System.Windows.Forms, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089</value></resheader>
'''
for i, lang in enumerate(LANGS):
    rows = [(k, v[i]) for k, v in S.items()]
    for k, forms in P.items():
        rows += [(f'{k}.{cat}', text) for cat, text in forms[lang].items()]
    body = ''.join(f'  <data name="{escape(k)}" xml:space="preserve"><value>{escape(v)}</value></data>\n' for k, v in sorted(rows))
    name = 'AppResources.resx' if lang == 'en' else f'AppResources.{lang}.resx'
    with open(os.path.join(out, name), 'w', encoding='utf-8') as f:
        f.write(header + body + '</root>\n')
    print(name, len(rows))
